import{_ as o,l as n,o as t,c as l,v as m,p as d,x as r,d as s,i as g,S as p,b as e}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"嵌入初始化与尺度","description":"","frontmatter":{"title":"嵌入初始化与尺度","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/embedding-init-scale.md","filePath":"llm/embedding-init-scale.md","lastUpdated":1789023840000}'),h={name:"llm/embedding-init-scale.md"};function c(E,a,u,P,f,_){const i=n("Mermaid");return t(),l("div",null,[a[1]||(a[1]=m('<h1 id="嵌入初始化与尺度" tabindex="-1">嵌入初始化与尺度 <a class="header-anchor" href="#嵌入初始化与尺度" aria-label="Permalink to &quot;嵌入初始化与尺度&quot;">​</a></h1><div class="epigraph"><p>输入嵌入是查找表，不是以扇入计的 GEMM；它的行范数直接成为残差流的起点，也直接乘进词表 softmax 的 logits。</p><footer>—— Vaswani et al., NeurIPS 2017 对嵌入乘 $\\sqrt{d_{\\mathrm{model}}}$；尺度随宽度的定标见 Yang 等，Tensor Programs V / μP</footer></div><p><a href="/llm/depth-scaled-init">上一课</a>把残差分支按层数缩小。缺口转到流的<strong>起点</strong>： <a href="/llm/embedding-lookup">嵌入查找</a> 的表 \\(E\\in\\mathbb{R}^{|V|\\times d}\\) 没有 fan-in 矩阵乘，Xavier 公式里的 \\(n_{\\mathrm{in}}\\) 不适用。行向量的 \\(\\ell_2\\) 范数决定第一步 LayerNorm 看见什么、注意力第一层的 \\(Q,K\\) 从哪来。Vaswani 等人在表上再乘 \\(\\sqrt{d_{\\mathrm{model}}}\\)；μP 则把输入层当成「有限宽到无限宽」的边界，学习率与方差另表。本课只钉输入表，输出头下一课才接。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>token id 的前向是 gather： \\(x_t=E_{w_t}\\)。没有「扇入个独立项相加」，方差不会自动按 \\(d\\) 平均掉。若每分量 \\(\\mathcal{N}(0,\\sigma^2)\\)，则行范数的期望大约 \\(\\sigma\\sqrt{d}\\)。\\(\\sigma=1\\) 时 \\(d=4096\\) 的行范数已是几十，第一层 <a href="/llm/rmsnorm">RMSNorm</a> 会把它们压回，但增益起步为 1 时，归一化前的动态范围已经进半精度的危险区；\\(\\sigma=0.02\\) 则行范数大约 \\(0.02\\sqrt{d}\\)，在 \\(d=768\\) 时约 0.55，在 \\(d=8192\\) 时约 1.8——同一魔法数随宽度漂。</p><p>位置编码（绝对正弦或 RoPE 的基）与 token 表相加或相乘，会再改起点。本课不重讲 RoPE，只要求：<strong>量初始尺度时，必须在「token + 位置」之后、第一层 LN 之前取范数</strong>，不要只打印 \\(E\\) 的直方图。</p><p><span class="marginnote">词表尾部的稀有 token 梯度稀疏，Adam 的二阶矩长期偏小，同样 \\(\\sigma\\) 下有效更新更大。初始化方差与 <a href="/llm/adamw">AdamW</a> 的分词频率纠缠，这是稳定性课才会展开的「嵌入学习率」问题；本课先把 \\(\\sigma\\) 与 \\(d\\) 的关系写对。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三种常见挂法，选一种写进配方。</p><p><strong>固定小标准差。</strong> GPT-2 / GPT-3 一类用 \\(\\sigma\\approx 0.02\\)，与残差投影同一数量级。宽度一变就必须重测行范数；它不是扇入公式。</p><p><strong>乘 \\(\\sqrt{d_{\\mathrm{model}}}\\)（Vaswani）。</strong> 表内用较小方差，查找后再乘 \\(\\sqrt{d}\\)，使嵌入进入后续层的幅度与 \\(d\\) 同阶。这与 SDPA 的 \\(1/\\sqrt{d_k}\\) 不是同一处旋钮：一个抬输入，一个压点积。两者同时用时要在 coord check 里看第一层注意力 logits，而不是各自「看起来都像论文」。</p><p><strong>μP 输入列。</strong> 输入嵌入的宽度维被当作 fan-out 增长：初始化方差与 Adam 学习率乘数跟隐藏层不同，避免加宽后第一步就把流放大。Yang 等人强调：把隐藏层的 \\(1/d\\) 错贴到嵌入，会出现「宽模型 logits 消失或爆炸」。实现上用 <code>infshape</code> 标记哪一维是宽度，不要手写一套与库不一致的表。</p><p><a href="/llm/tied-untied-embedding">Tied 嵌入</a> 把 \\(E\\) 与输出矩阵焊在一起，则本课的 \\(\\sigma\\) 同时决定初始 logits 幅度。untied 时可以输入小、输出更小（下一课）。先决定是否 tying，再选 \\(\\sigma\\)，顺序不能反。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RMSNorm 对每个位置做 \\(x/\\mathrm{RMS}(x)\\) 再乘 \\(\\gamma\\)。\\(\\gamma=1\\) 时，<strong>归一化后的</strong>尺度被钉住，看似嵌入 \\(\\sigma\\) 无关。训练初期 \\(\\gamma\\) 几乎不动，但残差加法发生在 Pre-LN 的主干上：未归一的 \\(x\\) 仍带着嵌入范数往上累加。所以「有 LN 就可以乱初始化嵌入」不成立——LN 管的是进 \\(F\\) 的分支，不管主干范数（Pre-LN）。Post-LN 把 LN 放在加法后，嵌入尺度会被每层打回，但对梯度雅可比不友好，不能当初始化的借口。</p><p>嵌入行之间的点积决定「哪些 token 一开始就被当成近邻」。过大的 \\(\\sigma\\) 让点积饱和，词表 softmax 一开始就自信而错；过小的 \\(\\sigma\\) 让所有 token 几乎不可分，前几步只在学一个均匀先验。合理起点是：未训练模型的 CE 接近 \\(\\log|V|\\)，略好或略差都可以，但不能差出一个数量级。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讨论 sentencepiece 词表大小——那是缩放单元的词表定律。也不讨论把嵌入从权重衰减里豁免：那是 <a href="/llm/adamw">AdamW</a> 分组，稳定性课会单写。多模态把图像码与文本码拼进同一张表或并列两张表时，两套熵不同，Chameleon 一类工作用 QK-Norm 补点积，不是把文本 \\(\\sigma\\) 原样贴到图像码上。</p>',18)),(t(),d(p,null,{default:r(()=>[g(i,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20ID%5B%22token%20id%22%5D%20--%3E%20LUT%5B%22%E6%9F%A5%E6%89%BE%20E%22%5D%0A%20%20LUT%20--%3E%20POS%5B%22%E5%8A%A0%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20POS%20--%3E%20RMS%5B%22%E7%AC%AC%E4%B8%80%E5%B1%82%20RMSNorm%20%E5%88%86%E6%94%AF%22%5D%0A%20%20POS%20--%3E%20STEM%5B%22Pre-LN%20%E4%B8%BB%E5%B9%B2%E7%B4%AF%E5%8A%A0%22%5D%0A%20%20SIG%5B%22sigma%20%E4%B8%8E%20d%22%5D%20--%3E%20LUT%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[s("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"嵌入是 gather，没有 Xavier 的扇入平均；行范数 \\(\\sim\\sigma\\sqrt{d}\\) 随宽度漂。"),e("li",null,"量尺度要在 token+位置之后、第一层 LN 之前。"),e("li",null,"固定 0.02、乘 \\(\\sqrt{d}\\)、μP 输入列三选一；tied 时输入 \\(\\sigma\\) 连着输出 logits。"),e("li",null,"Pre-LN 的主干不被 LN 钉死，有归一化仍要管嵌入范数。"),e("li",null,"出处：Vaswani et al., NeurIPS 2017；Yang 等，Tensor Programs V。")],-1))])}const b=o(h,[["render",c]]);export{A as __pageData,b as default};
